import java.util.ArrayList;
import java.util.List;

public final class ClaimFilter {

    public record Claim(String id, String status) {
    }

    public List<Claim> openOnly(List<Claim> claims) {
        List<Claim> open = new ArrayList<>();
        for (Claim claim : claims) {
            if (!claim.status().equals("OPEN")) {
                open.add(claim);
            }
        }
        return open;
    }
}

